param(
  [Parameter(Mandatory=$true)][string]$MakerToken,
  [Parameter(Mandatory=$true)][string]$CheckerToken,
  [Parameter(Mandatory=$true)][string]$TransferId,
  [string]$GatewayBaseUrl = 'http://127.0.0.1:18443'
)
$ErrorActionPreference = 'Stop'
$maker = @{ Authorization = "Bearer $MakerToken"; 'Content-Type' = 'application/json' }
$checker = @{ Authorization = "Bearer $CheckerToken"; 'Content-Type' = 'application/json' }
$decision = $null
try {
  $decision = Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/operations/v1/risk/evaluate" -Headers $maker -Body (@{transferId=$TransferId;amount='20000'}|ConvertTo-Json)
  if ($decision.decision -ne 'REVIEW') { throw "Expected REVIEW, got $($decision.decision)" }
  $selfStatus = 0
  try { Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/operations/v1/risk/$($decision.decisionId)/approve?version=1&reason=self" -Headers $maker | Out-Null }
  catch { $selfStatus = $_.Exception.Response.StatusCode.value__ }
  if ($selfStatus -ne 409) { throw "Expected maker self-approval 409, got $selfStatus" }
  $approved = Invoke-RestMethod -Method Post -Uri "$GatewayBaseUrl/api/operations/v1/risk/$($decision.decisionId)/approve?version=1&reason=independent" -Headers $checker
  if ($approved.decision -ne 'ALLOW') { throw "Expected ALLOW, got $($approved.decision)" }
  Write-Output "RISK=PASS decision=REVIEW selfCheck=409 checker=ALLOW decisionId=$($decision.decisionId)"
}
finally {
  if ($null -ne $decision) { docker exec mifos-channel-bank-channel-postgres-1 psql -U bank_channel -d bank_channel -c "delete from risk_decision where decision_id='$($decision.decisionId)';" | Out-Null }
}

package local.bank.channel.documents;

import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;

@RestController
public class LoanDocumentController {
  private final JdbcTemplate jdbc;
  public LoanDocumentController(JdbcTemplate jdbc){this.jdbc=jdbc;}
  @PostMapping("/api/customer/v1/loans/applications/{id}/documents")
  public Map<String,Object> add(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@RequestBody Request request){
    if(request.documentType()==null||request.documentType().isBlank()||request.storageRef()==null||request.storageRef().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Document metadata is required");
    Integer owned=jdbc.queryForObject("SELECT count(*) FROM loan_application WHERE application_id=? AND subject=?",Integer.class,id,jwt.getSubject());if(owned==null||owned==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Application not found");UUID doc=UUID.randomUUID();jdbc.update("INSERT INTO loan_document(document_id,application_id,subject,document_type,storage_ref) VALUES(?,?,?,?,?)",doc,id,jwt.getSubject(),request.documentType(),request.storageRef());return Map.of("documentId",doc.toString(),"status","RECEIVED","documentType",request.documentType());
  }
  @GetMapping("/api/customer/v1/loans/applications/{id}/documents")
  public Map<String,Object> list(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id){return Map.of("items",jdbc.query("SELECT document_id,document_type,status FROM loan_document WHERE application_id=? AND subject=? ORDER BY created_at",(rs,n)->Map.of("documentId",rs.getString(1),"documentType",rs.getString(2),"status",rs.getString(3)),id,jwt.getSubject()));}
  public record Request(String documentType,String storageRef){}
}

package local.bank.channel.payments;

import java.util.Map;
import java.util.UUID;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
public class MockClearingController {
  private final MockClearingService service;
  public MockClearingController(MockClearingService service){this.service=service;}
  @PostMapping("/api/operations/v1/clearing/payments")
  public Map<String,Object> submit(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key") String key,@RequestBody Request request){return service.submit(UUID.fromString(request.transferId()),request.scenario(),key);}
  @PostMapping("/internal/mock-clearing/{clearingId}/deliver/{sequence}")
  public Map<String,Object> deliver(@PathVariable UUID clearingId,@PathVariable int sequence){return service.deliver(clearingId,sequence);}
  public record Request(String transferId,String scenario){}
}
